<script setup lang="ts">
import { computed, nextTick, ref } from 'vue';
import type { FitnessPhotoDraft } from '@xvyin/contracts';
import type { MediaItem } from '../api';
import { appendReadyPhotos, applyPhotoMetadata } from '../photo-selection';
import AssetField from './AssetField.vue';
import MediaPicker from './MediaPicker.vue';
const props = withDefaults(defineProps<{ modelValue: FitnessPhotoDraft[]; limit?: number }>(), { limit: 100 });
const emit = defineEmits<{ 'update:modelValue': [value: FitnessPhotoDraft[]] }>();
const dragged = ref<number | null>(null), picker = ref(false), page = ref(1), list = ref<HTMLElement>(), pageSize = 12;
const pageCount = computed(() => Math.max(1, Math.ceil(props.modelValue.length / pageSize)));
const pagePhotos = computed(() => props.modelValue.map((photo, index) => ({ photo, index })).slice((Math.min(page.value, pageCount.value) - 1) * pageSize, Math.min(page.value, pageCount.value) * pageSize));
const selected = computed(() => props.modelValue.filter(photo => photo.status === 'published').length);
const availableDrafts = computed(() => props.modelValue.filter(photo => photo.status === 'draft' && photo.assetId).length);
function move(index: number, to: number) { if (to < 0 || to >= props.modelValue.length) return; const photos = [...props.modelValue]; const moved = photos.splice(index, 1)[0]; if (!moved) return; photos.splice(to, 0, moved); emit('update:modelValue', photos.map((photo, i) => ({ ...photo, sortOrder: i }))); }
function remove(index: number) { emit('update:modelValue', props.modelValue.filter((_, i) => i !== index).map((photo, i) => ({ ...photo, sortOrder: i }))); }
function includeDrafts() { emit('update:modelValue', props.modelValue.map(photo => photo.status === 'draft' && photo.assetId ? { ...photo, status: 'published' as const } : photo)); }
async function append(items: MediaItem[]) { const next = appendReadyPhotos(props.modelValue, items, props.limit); emit('update:modelValue', next); page.value = Math.max(1, Math.ceil(next.length / pageSize)); await nextTick(); list.value?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
async function changePage(next: number) { page.value = next; await nextTick(); list.value?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
</script>
<template><section ref="list" class="photo-editor"><div class="photo-toolbar"><div><h2>照片与图注</h2><span class="hint">{{ modelValue.length }} / {{ limit }} 张 · 支持一次添加多张</span></div><button type="button" class="primary" :disabled="modelValue.length >= limit" @click="picker = true">＋ 添加照片</button></div><p class="hint mt16">直接上传或从媒体库多选，完成后自动添加到列表末尾。拍摄日期会从照片中读取，可手动修改；替代文字默认使用文件名，请按画面完善。</p><div v-if="!modelValue.length" class="empty mt16"><h3>还没有关联照片</h3><p>一次选好照片，再补充图注、预览和发布。</p><button type="button" class="mt16" @click="picker = true">上传或选择照片</button></div><div v-if="modelValue.length" class="photo-publication" :class="{ 'none-selected': !selected }"><div><strong>{{ selected }} / {{ modelValue.length }} 张照片将随记录公开</strong><p>新添加的照片先保存为草稿。选为“随本条记录发布”后才会进入网站。</p></div><button v-if="availableDrafts" type="button" @click="includeDrafts">让 {{ availableDrafts }} 张草稿照片随记录发布</button></div><nav v-if="pageCount > 1" class="flex between mt16" aria-label="照片编辑分页"><button type="button" :disabled="page <= 1" @click="changePage(page - 1)">上一页</button><span>{{ Math.min(page, pageCount) }} / {{ pageCount }} 页 · 每页 {{ pageSize }} 张</span><button type="button" :disabled="page >= pageCount" @click="changePage(page + 1)">下一页</button></nav><article v-for="{ photo, index } in pagePhotos" :key="photo.id" class="content-block mt16" @dragover.prevent @drop.prevent="dragged !== null && move(dragged, index); dragged = null"><header class="block-head"><strong><span draggable="true" class="drag-handle" aria-hidden="true" @dragstart="dragged = index">⠿</span>照片 {{ index + 1 }} <span class="photo-state">{{ { draft: '暂留草稿', published: '随记录公开', hidden: '已隐藏' }[photo.status] }}</span></strong><div class="flex row-actions"><button type="button" :disabled="index === 0" aria-label="照片上移" @click="move(index, index - 1)">↑</button><button type="button" :disabled="index === modelValue.length - 1" aria-label="照片下移" @click="move(index, index + 1)">↓</button><button type="button" class="danger" @click="remove(index)">移除</button></div></header><div class="block-body"><AssetField v-model="photo.assetId" label="照片" kind="image" @selected="item => applyPhotoMetadata(photo, item)"/><div class="form-grid mt16"><label class="field">替代文字<input v-model="photo.alt" maxlength="500" required placeholder="描述画面内容"></label><label class="field">拍摄日期，可留空<input :value="photo.photoDate ?? ''" type="date" @input="photo.photoDate = ($event.target as HTMLInputElement).value || null"></label><label class="field">发布状态<select v-model="photo.status"><option value="draft">暂留草稿</option><option value="published">随本条记录发布</option><option value="hidden">隐藏</option></select></label><label class="field span2">图注<textarea v-model="photo.caption" maxlength="1000" rows="3"></textarea></label></div><label class="check mt16"><input v-model="photo.featured" type="checkbox">在首页精选中使用</label></div></article><div v-if="modelValue.length" class="photo-bottom"><button type="button" class="primary" :disabled="modelValue.length >= limit" @click="picker = true">＋ 继续添加照片</button><nav v-if="pageCount > 1" class="flex" aria-label="照片编辑底部分页"><button type="button" :disabled="page <= 1" @click="changePage(page - 1)">上一页</button><span>{{ Math.min(page, pageCount) }} / {{ pageCount }}</span><button type="button" :disabled="page >= pageCount" @click="changePage(page + 1)">下一页</button></nav></div><MediaPicker v-if="picker" kind="image" title="添加照片" multiple :max-selected="limit - modelValue.length" :exclude-ids="modelValue.map(photo => photo.assetId)" @close="picker = false" @select-many="append"/></section></template>
<style scoped>.photo-editor{scroll-margin-top:100px}.photo-toolbar{position:sticky;top:0;z-index:4;display:flex;justify-content:space-between;align-items:center;gap:16px;background:var(--paper,#faf9f6);padding:14px 0;border-bottom:1px solid var(--line)}.photo-toolbar>div{display:grid;gap:5px}.photo-toolbar>button{flex-shrink:0}.photo-publication{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:20px;padding:18px 0;border-block:1px solid var(--line);font-size:13px}.photo-publication>div{min-width:0}.photo-publication p{font-size:12px;color:var(--muted);line-height:1.8;margin-top:6px;max-width:56ch}.photo-publication.none-selected strong{color:var(--red)}.photo-publication>button{flex-shrink:0;font-size:12px}.photo-state{font-size:11px;font-weight:400;margin-left:12px;color:var(--muted)}.photo-bottom{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:24px 0}.photo-editor nav span{font-size:12px;color:var(--muted)}@media(max-width:780px){.photo-publication{align-items:flex-start;flex-direction:column;gap:12px}.photo-publication>button{max-width:100%;white-space:normal}.photo-state{display:block;margin:5px 0 0}.photo-toolbar h2{font-size:19px}.photo-toolbar .hint{font-size:11px}.photo-toolbar button{padding:9px 12px}}
</style>
